-- Each sheet's rate for a grade: a percent, 0.00 or more with two decimals. A grade with no row has
-- no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)    NOT NULL,
    pct      DECIMAL(7, 2) NOT NULL CHECK (pct >= 0)
);
CREATE UNIQUE INDEX rate_sheet_grade ON rate (sheet_id, grade);
-- A rate applies from its from-date on; a rate with no from-date applies from the beginning of
-- time. A grade may have several rates, one per from-date (one with none).
ALTER TABLE rate ADD COLUMN from_date DATE;
DROP INDEX rate_sheet_grade;
CREATE UNIQUE NULLS NOT DISTINCT INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_date);
-- A rate may also have a to-date: it applies through it (included). A rate with none applies on with
-- no end.
ALTER TABLE rate ADD COLUMN to_date DATE;
-- A rate is kept as versions: setting a rate for a grade and from-date that already exist keeps the
-- value it replaces as an older version. The rate row holds the newest version (the one in force) and
-- its version number, which is also how many versions it has; rate_version holds the older ones.
ALTER TABLE rate ADD COLUMN version INT NOT NULL DEFAULT 1;
CREATE TABLE rate_version (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    rate_id  BIGINT        NOT NULL REFERENCES rate (id),
    version  INT           NOT NULL,
    pct      DECIMAL(7, 2) NOT NULL CHECK (pct >= 0),
    to_date  DATE
);
CREATE UNIQUE INDEX rate_version_rate ON rate_version (rate_id, version);
-- A claim opened while its due is above the sheet's review threshold goes to REVIEW until a steward reviews it.
ALTER TABLE claim DROP CONSTRAINT claim_status;
ALTER TABLE claim ADD CONSTRAINT claim_status CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'DELETED', 'REVIEW'));

